{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C21", "C23", "C02", "C11", "C24", "C03", "C04", "C19", "C18", "C20"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C21", "C23", "C02", "C11", "C24", "C03", "C04", "C19", "C18", "C20"],
  "claims": [
    {
      "claim": "Ketanserin, the closest structural context sharing the 4-fluorophenyl ketone, piperidine, and cyclic-urea pharmacophore, has absolute oral bioavailability of 49.3 ± 18.0% (range 27–69%) by the AUC method and 60% by F = 1 − E after 40 mg oral tablets in fasted subjects; both exceed the 20% threshold.",
      "card_ids": ["C21", "C23"]
    },
    {
      "claim": "Sertindole, a piperidine/fluorophenyl cyclic-urea analogue, has human oral bioavailability of approximately 74–75% with little effect from food.",
      "card_ids": ["C02", "C11", "C24"]
    },
    {
      "claim": "Trazodone, an N-alkylated halophenyl heterocycle with a propyl linker, has absolute oral bioavailability of 63–91% across fasted and fed populations.",
      "card_ids": ["C03", "C04", "C19"]
    },
    {
      "claim": "Less similar contexts also exceed 20%: setipiprant has human oral bioavailability of at least 50%, and maraviroc has fasted F of 24% at 100 mg.",
      "card_ids": ["C18", "C20"]
    },
    {
      "claim": "L3 oral exposure records are mostly for unrelated molecules; the closest structurally related trazpiroben record shows measurable oral Cmax after 25 mg, consistent with oral absorption but without an IV comparator or F value.",
      "card_ids": ["C68"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C68"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute F measurement for the exact query molecule.",
    "L3 provides oral AUC/Cmax only, not F; the closest trazpiroben record (C68) lacks an IV comparator.",
    "Query is zwitterionic (neutral fraction 0, logD -0.76); no transporter, efflux, or first-pass data are available.",
    "Ketanserin transfer is based on 40 mg tablet fasted data; dose and formulation effects for the query are unknown."
  ],
  "decision_summary": "High is retained with moderate confidence. The closest L1 context, ketanserin, reports absolute F of about 49–60%, and related piperidine/fluorophenyl cyclic-urea contexts report F of 74–75% (sertindole) and 63–91% (trazodone); even the lowest related value, maraviroc at 24%, exceeds 20%. L3 oral exposure records do not provide direct F for the query; the only structurally related trazpiroben record shows measurable oral Cmax but no F, so it does not change the decision. The unfavorable passive-permeability prior is an uncertainty, not affirmative evidence for F <20%."
}

